 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    divider = next((r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != bg), None)
    if divider is None:
        return g
    line_color = g[divider][0]
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (bg, line_color)]
    if not cells:
        return g
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    obj = [[g[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
    for r, c in cells:
        g[r][c] = bg
    if r0 > divider:
        nr0 = divider + 1
        for i, row in enumerate(obj):
            g[nr0 + i][c0:c1 + 1] = row
        if nr0 + len(obj) < h:
            g[nr0 + len(obj)] = [8] * w
    else:
        nr0 = divider - len(obj)
        for i, row in enumerate(obj):
            g[nr0 + i][c0:c1 + 1] = row
        if nr0 - 1 >= 0:
            g[nr0 - 1] = [8] * w
    return g
